typedef unsigned char uint8;
typedef unsigned int uint32;

class vector3d
{
public:
  float x, y, z;
};

class color32
{
public:
  union
  {
    struct { uint8 b, g, r, a; } c;
    uint32 i;
  };

  color32(uint32 ic = 0) : i(ic) {}
  color32(uint8 _r, uint8 _g, uint8 _b, uint8 _a = 255)
  {
    c.b = _b; c.g = _g; c.r = _r; c.a = _a;
  }
  uint8 get_alpha() const { return c.a; }
  void set_alpha(uint8 arg) { c.a = arg; }
};

#define color32_white color32(255, 255, 255, 255)

class entity
{
  char pad0[64];
  vector3d rel_position;
  char pad1[396];
  color32 render_color;
public:
  const vector3d& get_rel_position() const { return rel_position; }
  void set_render_color(const color32 new_color) { render_color = new_color; }
};

extern float WAVE_MeshMaxZ;

template<class T> inline const T& min(const T& a, const T& b)
{
  return b < a ? b : a;
}

class water_object
{
  char pad0[40];
  entity *my_entity;
  char pad1[16];
  color32 ren_col;
  float my_max_alpha;
  char pad2[624];
  float fade_distance;
public:
  bool update(float dt) __asm__("update__12water_objectf");
};

// base update function that makes the objects fade
bool water_object::update (float dt)
{
  vector3d position (my_entity->get_rel_position ());

  // remove tinting to fix the sorting bug for now until we find the cause of the problem
  my_entity->set_render_color (color32_white);

  // fade object
  if (((fade_distance >= 0) && (position.z > WAVE_MeshMaxZ + fade_distance)) || (my_max_alpha != 1.0f))
  {
    float blend;

    blend = min (my_max_alpha, 1.0f - ((position.z - (WAVE_MeshMaxZ + fade_distance)) / 50));

    if (blend < 0.025f)
    {
      color32 col = ren_col;
      col.set_alpha (0);
      my_entity->set_render_color (col);

      return false;
    }
    else
    {
      color32 col = ren_col;
      col.set_alpha (ren_col.get_alpha () * blend);
      my_entity->set_render_color (col);
    }
  }

  return true;
}
